def summarize(values):
    """Return count/sum/min/max for a list of non-bool integers."""
    if type(values) is not list:
        raise ValueError('values must be a built-in list')
    items = values[:]
    for item in items:
        if type(item) is not int:
            raise ValueError('every item must be a built-in int (bool not allowed)')
    if not items:
        return {'count': 0, 'sum': 0, 'min': None, 'max': None}
    total = 0
    lowest = highest = items[0]
    for item in items:
        total += item
        if item < lowest:
            lowest = item
        if item > highest:
            highest = item
    return {'count': len(items), 'sum': total, 'min': lowest, 'max': highest}

