import unittest
from summary import summarize

class FrozenAcceptance(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(summarize([]), {'count':0, 'sum':0, 'min':None, 'max':None})
    def test_single(self):
        self.assertEqual(summarize([7]), {'count':1, 'sum':7, 'min':7, 'max':7})
    def test_mixed(self):
        self.assertEqual(summarize([3,-4,0,3]), {'count':4, 'sum':2, 'min':-4, 'max':3})
    def test_large(self):
        big=10**50
        self.assertEqual(summarize([big,-big,1]), {'count':3, 'sum':1, 'min':-big, 'max':big})
    def test_input_unchanged(self):
        data=[3,1,2];before=data.copy();summarize(data);self.assertEqual(data,before)
    def test_non_list(self):
        class ListSubclass(list): pass
        for data in (None, (), '', {}, iter([1]), ListSubclass([1])):
            with self.subTest(data=type(data).__name__):
                with self.assertRaises(ValueError):summarize(data)
    def test_invalid_items(self):
        class IntSubclass(int): pass
        for item in (True, False, 1.0, '1', None, [], {}, IntSubclass(1)):
            with self.subTest(item=type(item).__name__):
                with self.assertRaises(ValueError):summarize([1,item])
    def test_finite_independent_domain(self):
        import itertools
        for size in range(5):
            for values in itertools.product((-2,0,3),repeat=size):
                data=list(values)
                expected=dict(count=len(data),sum=sum(data),min=min(data) if data else None,max=max(data) if data else None)
                self.assertEqual(summarize(data),expected)

if __name__=='__main__':unittest.main()
